const paths={grid:'M3 3h7v7H3z M14 3h7v7h-7z M3 14h7v7H3z M14 14h7v7h-7z',file:'M14 2H6a2 2 0 0 0-2 2v16a2 2 0 0 0 2 2h12a2 2 0 0 0 2-2V8z M14 2v6h6 M8 13h8 M8 17h6',layers:'m12 3 10 6-10 6L2 9z M2 13l10 6 10-6 M2 17l10 6 10-6',building:'M4 22V4h12v18 M16 10h4v12 M8 8h4 M8 12h4 M8 16h4 M8 22v-3h4v3',cloud:'M6 18a5 5 0 1 1 1-10 7 7 0 0 1 13 3 4 4 0 0 1-1 7 M9 16l3-3 3 3 M12 13v9',plus:'M12 5v14 M5 12h14',arrow:'M5 12h14 M13 6l6 6-6 6',search:'M21 21l-5-5 M18 10a8 8 0 1 1-16 0 8 8 0 0 1 16 0',check:'m5 12 4 4L19 6',clock:'M12 8v5l3 2 M22 12a10 10 0 1 1-20 0 10 10 0 0 1 20 0',download:'M12 3v12 M7 10l5 5 5-5 M4 17v4h16v-4',share:'M18 8a3 3 0 1 0 0-6 3 3 0 0 0 0 6 M6 15a3 3 0 1 0 0-6 3 3 0 0 0 0 6 M18 22a3 3 0 1 0 0-6 3 3 0 0 0 0 6 M8.5 10.5l7-4 M8.5 13.5l7 4',camera:'M4 6h4l2-3h4l2 3h4v15H4z M16 13a4 4 0 1 1-8 0 4 4 0 0 1 8 0',spark:'m12 3 2.5 6.5L21 12l-6.5 2.5L12 21l-2.5-6.5L3 12l6.5-2.5z',menu:'M4 6h16 M4 12h16 M4 18h16',x:'M6 6l12 12 M18 6 6 18',settings:'M12 8a4 4 0 1 0 0 8 4 4 0 0 0 0-8 M12 2v3 M12 19v3 M2 12h3 M19 12h3 M5 5l2 2 M17 17l2 2 M5 19l2-2 M17 7l2-2',mail:'M3 5h18v14H3z M3 5l9 8 9-8',copy:'M8 8h13v13H8z M3 16V3h13',shield:'m12 2 9 4v6c0 5-9 10-9 10S3 17 3 12V6z m-4 10 3 3 5-6'};
const icon=(name,cls='')=>`<svg class="icon ${cls}" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.7" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true"><path d="${paths[name]||paths.file}"/></svg>`;
const state={view:'dashboard',reports:[],companies:[],companyId:'',report:null,tab:0,query:'',filter:'all',companyEdit:null,customers:[],sites:[],equipment:[],reportTemplates:[],tasks:[],workOrders:[],manuals:[],alertRules:[],people:[],teamUsers:[],opsFilter:{}};
const tabs=['Servicio','Equipos','Mediciones','Inspección','Redacción','Evidencias','Hallazgos','Revisión'];
let dirty=false,saveTimer,installPrompt,updateRegistration,savePending=0;
const $=s=>document.querySelector(s);
function toast(message,error=false){const t=$('#toast');t.textContent=message;t.className='visible'+(error?' error':'');clearTimeout(toast.timer);toast.timer=setTimeout(()=>t.className='',4500);}
async function reload(){state.reports=(await db.all('reports')).filter(r=>canCompany(syncState.user,r.companyId)).sort((a,b)=>b.updatedAt.localeCompare(a.updatedAt));state.companies=(await db.all('companies')).filter(c=>canCompany(syncState.user,c.id));if(state.companyId&&!state.companies.some(c=>c.id===state.companyId))state.companyId=state.companies[0]?.id||'';await Promise.all(catalogKinds.map(async kind=>{state[kind]=(await db.all(kind)).filter(row=>canCompany(syncState.user,row.companyId));}));}
function company(){return state.companies.find(c=>c.id===state.companyId)||state.companies[0];}
const labelSync=r=>r._sync?.conflict?'Conflicto':r._sync?.dirty?'Pendiente de sincronizar':'Sincronizado';
function status(r){return `<span class="pill ${r.status==='Emitido'?'green':r.status==='En revisión'?'amber':'neutral'}">${e(r.status)}</span>`;}
function empty(title,description,action='new',button='Crear informe'){return `<div class="empty-state">${icon('file')}<h3>${title}</h3><p>${description}</p><button class="btn primary" data-action="${action}">${icon('plus')}${button}</button></div>`;}
function bindGlobalErrors(){window.addEventListener('unhandledrejection',event=>{console.error(event.reason);toast(event.reason?.message||'No se completó la operación. Revisa e inténtalo nuevamente.',true);});window.addEventListener('beforeunload',event=>{if(dirty||savePending){event.preventDefault();event.returnValue='';}});document.addEventListener('visibilitychange',()=>{if(document.hidden)void persist();});}
function field(label,path,value,{type='text',placeholder='',wide=false,options=null,required=false}={}){const disabled=state.report?.status!=='Borrador'&&state.view==='editor';return `<label class="field ${wide?'wide':''}"><span>${e(label)}${required?' <b>*</b>':''}</span>${options?`<select data-field="${path}" ${disabled?'disabled':''}>${options.map(o=>`<option value="${e(o)}" ${String(value)===o?'selected':''}>${e(o||'Sin evaluar')}</option>`).join('')}</select>`:type==='textarea'?`<textarea data-field="${path}" rows="5" placeholder="${e(placeholder)}" ${disabled?'disabled':''}>${e(value)}</textarea>`:`<input data-field="${path}" type="${type}" value="${e(value)}" placeholder="${e(placeholder)}" ${disabled?'disabled':''} ${type==='number'?'step="any"':''}>`}</label>`;}
function navItem(view,label,i){return `<button data-action="nav" data-view="${view}" class="nav-link ${state.view===view?'active':''}">${icon(i)}<span>${label}</span>${state.view===view?'<i></i>':''}</button>`;}
function render(){
 if(syncState.user?.role==='client'){void renderPortal(enterpriseContext());return;}
 const c=company(),titles={diagnostics:['Servicios listos para trabajar','Configuración y diagnóstico'],dashboard:['Tu operación, documentada.','Visión general'],reports:['Todos tus informes','Biblioteca de documentos'],templates:['Un punto de partida para cada trabajo','Plantillas profesionales'],directory:['Clientes e instalaciones','Directorio de operaciones'],equipment:['Cada equipo tiene una historia','Registro de activos'],tasks:['Cada pendiente, con seguimiento','Acciones y responsables'],workOrders:['Planifica la próxima intervención','Órdenes y mantenimiento'],manuals:['Conocimiento autorizado de tu empresa','Biblioteca técnica'],alertRules:['Criterios que generan alertas','Reglas técnicas'],team:['Personas, permisos y servicios','Administración avanzada'],companies:['La identidad de tu empresa','Empresas y marca'],sync:['Todo en su lugar, en cualquier dispositivo','Sincronización'],editor:[state.report?.folio||'Nuevo informe',templates[state.report?.template]?.shortLabel||'Editor']};const [title,eyebrow]=titles[state.view];
 $('#app').innerHTML=`<div class="shell"><aside class="sidebar" id="sidebar"><a class="brand" href="#" data-action="home"><span class="brand-square">S<i></i></span><div><b>SOLIS<span>FIELD</span></b><small>DOCUMENTOS PROFESIONALES</small></div></a><div class="workspace-select"><span>ESPACIO DE TRABAJO</span><select id="company-switch" aria-label="Empresa activa">${state.companies.map(c=>`<option value="${c.id}" ${c.id===state.companyId?'selected':''}>${e(c.tradeName||c.name||'Mi empresa')}</option>`).join('')}</select></div><nav>${navItem('dashboard','Vista general','grid')}${navItem('reports','Informes','file')}${navItem('templates','Plantillas','layers')}${navItem('directory','Clientes e instalaciones','building')}${navItem('equipment','Equipos e historial','settings')}${navItem('tasks','Seguimiento de acciones','check')}${navItem('workOrders','Órdenes y mantenimiento','clock')}${navItem('manuals','Biblioteca técnica','layers')}<div class="nav-label">ADMINISTRACIÓN</div>${navItem('companies','Empresas y marca','building')}${navItem('sync','Sincronización','cloud')}${navItem('alertRules','Reglas de alertas','shield')}${navItem('team','Equipo y servicios','settings')}${navItem('diagnostics','Configuración y diagnóstico','shield')}</nav><div class="sidebar-bottom"><div class="offline-card"><span class="connection-dot"></span><b id="connection-title">${navigator.onLine?'Disponible en terreno':'Modo offline'}</b><p>Tu trabajo se guarda en este dispositivo.</p></div><button class="nav-link" data-action="backup">${icon('download')}<span>Descargar respaldo</span></button><div class="profile"><span>${e((c?.name||'S').slice(0,2).toUpperCase())}</span><div><b>${e(c?.tradeName||c?.name||'Configura tu empresa')}</b><small>Field Pro · v3.4.0</small></div></div></div></aside><div class="main"><header class="topbar"><div class="topbar-left"><button class="icon-btn mobile-menu" data-action="menu" aria-label="Abrir menú">${icon('menu')}</button><span>ESPACIO DE TRABAJO</span><b>${e(c?.tradeName||c?.name||'Mi empresa')}</b></div><div class="topbar-actions"><button class="sync-indicator" data-action="sync-now" title="Ver sincronización"><span class="connection-dot"></span><span id="sync-label">${e(syncState.message)}</span></button><button class="btn primary small" data-action="new">${icon('plus')}<span>Nuevo informe</span></button></div></header><main id="content"><div class="page-heading"><div><div class="eyebrow">${e(eyebrow)}</div><h1>${e(title)}</h1></div><span class="date-label">${new Date().toLocaleDateString('es-CL',{day:'numeric',month:'long',year:'numeric'})}</span></div>${state.view==='dashboard'?operationDashboard(state):state.view==='reports'?reportsView():state.view==='templates'?templatesView():operationKinds.includes(state.view)?operationsView(state,state.view):state.view==='team'?accountsView():state.view==='directory'?directoryView(state):state.view==='equipment'?equipmentView(state):state.view==='companies'?companiesView():state.view==='sync'?syncView():state.view==='diagnostics'?diagnosticsView():editorView()}</main><footer class="app-footer"><span>SOLIS Field Pro</span><span>Creado para acompañarte en terreno.</span></footer></div></div>`;
 if(state.view==='editor'){bindEditor();refreshWorkflowNotice(enterpriseContext());}
 if(state.view==='companies')bindCompany();
 if(state.view==='sync'){renderConflicts();renderRecoveryStatus(enterpriseContext()).catch(error=>toast(error.message,true));}
 updateSyncUI();
}
function dashboard(){
 const docs=state.reports.filter(r=>r.companyId===company()?.id),draft=docs.filter(r=>r.status==='Borrador').length,issued=docs.filter(r=>r.status==='Emitido').length,pending=docs.filter(r=>r._sync?.dirty).length;
 const latest=docs.filter(r=>!docs.some(other=>other.folio===r.folio&&(other.revision||0)>(r.revision||0)));const actions=latest.flatMap(r=>[...(r.actions||[]).filter(a=>a.status!=='Completada'),...(r.findings||[]).filter(f=>f.status!=='Resuelto').map(f=>({...f,description:f.title}))].map(a=>({...a,report:r}))).sort((a,b)=>({Crítica:0,Alta:1,Media:2,Baja:3}[a.priority]??4)-({Crítica:0,Alta:1,Media:2,Baja:3}[b.priority]??4)).slice(0,4);
 return `<section class="hero"><div class="hero-copy"><span class="hero-kicker"><i></i> DEL TERRENO AL INFORME</span><h2>Tu experiencia técnica.<br><em>Una presentación impecable.</em></h2><p>Registra evidencias, transforma tus notas en informes y entrega documentos con la identidad de tu empresa.</p><button class="btn light" data-action="new">Crear un informe ${icon('arrow')}</button><small>${icon('shield')} Guardado local · Trabajo sin conexión</small></div><div class="hero-doc" aria-hidden="true"><div class="mini-doc-top"><span>${cLogo()}</span><b>INFORME TÉCNICO</b></div><h3>Inspección y<br>evaluación en terreno</h3><div class="mini-lines"><i></i><i></i><i></i></div><div class="mini-facts"><span>IDENTIFICACIÓN</span><b>Equipo / sistema</b><span>RESULTADO</span><b class="mini-check">✓ Evidencias documentadas</b></div><div class="mini-table"><i></i><i></i><i></i></div><div class="mini-seal">${icon('check')} FORMATO PROFESIONAL</div></div><span class="hero-orbit one"></span><span class="hero-orbit two"></span></section>
 <section class="stats-grid">${[['file',docs.length,'Informes creados','Tu biblioteca técnica'],['clock',draft,'En elaboración','Continúa donde quedaste'],['check',issued,'Documentos emitidos','Con versión conservada'],['cloud',pending,'Pendientes de sincronizar',navigator.onLine?'Se sincronizan al iniciar sesión':'Guardados en el dispositivo']].map(([ic,n,title,desc])=>`<article class="stat-card"><div><span class="stat-icon">${icon(ic)}</span><span class="stat-dots">···</span></div><b>${n}</b><h3>${title}</h3><p>${desc}</p></article>`).join('')}</section>
 <div class="dashboard-grid"><section class="panel"><div class="panel-heading"><div><h2>Informes recientes</h2><p>Tu actividad, siempre a mano.</p></div><button class="text-btn" data-action="nav" data-view="reports">Ver todos ${icon('arrow')}</button></div>${docs.length?`<div class="report-list">${docs.slice(0,5).map(reportCard).join('')}</div>`:empty('Tu próximo informe empieza aquí','Elige una plantilla y documenta tu primer trabajo.')}</section><aside class="side-panels"><section class="panel quick-panel"><span class="eyebrow">EMPIEZA CON UNA BASE</span><h2>¿Qué vas a documentar?</h2>${['general','proposal','diagnostic','evaluation'].map(k=>`<button data-action="create" data-template="${k}"><span class="template-symbol">${templates[k].icon}</span><div><b>${templates[k].shortLabel}</b><small>${templates[k].defaultService}</small></div>${icon('arrow')}</button>`).join('')}</section><section class="panel action-panel"><div class="panel-heading"><h2>Acciones pendientes</h2><span class="pill neutral">${actions.length}</span></div>${actions.length?actions.map(a=>`<button class="pending-action" data-action="open" data-id="${a.report.id}"><i class="priority-dot ${a.priority==='Alta'?'high':''}"></i><div><b>${e(a.description)}</b><small>${e(a.owner||'Sin responsable')} · ${e(fmtDate(a.dueDate))}</small></div></button>`).join(''):'<p class="muted">Las acciones que registres en tus informes aparecerán aquí.</p>'}</section></aside></div>`;
}
function cLogo(){const c=company();return safeImage(c?.logo)?`<img src="${safeImage(c.logo)}" alt="">`:e((c?.tradeName||c?.name||'EMPRESA').slice(0,16));}
function reportCard(r){const t=templates[r.template]||templates.general;return `<article class="report-card"><button class="report-open" data-action="open" data-id="${r.id}"><span class="report-symbol ${r.template==='proposal'?'gold':''}">${e(t.icon)}</span><div><span class="report-folio">${e(r.folio)} <small>Rev. ${r.revision||0}</small></span><h3>${e(r.title||t.title)}</h3><p>${e(r.customerCompany||'Cliente pendiente')} <span>·</span> ${e(fmtDate(r.serviceDate))}</p></div></button><div class="report-end">${status(r)}<small class="row-sync">${e(labelSync(r))}</small><button class="icon-btn" data-action="report-menu" data-id="${r.id}" aria-label="Opciones de ${e(r.folio)}">···</button></div></article>`;}
function filteredReports(){return state.reports.filter(r=>r.companyId===company()?.id&&(state.filter==='all'||r.status===state.filter)&&`${r.folio} ${r.title} ${r.customerCompany} ${r.site} ${r.equipment.assetTag}`.toLowerCase().includes(state.query.toLowerCase()));}
function reportsView(){const list=filteredReports();return `<section class="panel library-panel"><div class="library-toolbar"><label class="search-box">${icon('search')}<input id="report-search" placeholder="Buscar por cliente, folio, equipo o instalación" value="${e(state.query)}"></label><select id="status-filter" aria-label="Filtrar por estado">${['all','Borrador','En revisión','Aprobado','Emitido'].map(v=>`<option value="${v}" ${state.filter===v?'selected':''}>${v==='all'?'Todos los estados':v}</option>`).join('')}</select><button class="btn secondary" data-action="import">${icon('download')} Importar</button><button class="text-btn" data-action="trash">Papelera</button></div><div id="report-results">${list.length?list.map(reportCard).join(''):empty('Sin informes para mostrar','Crea un documento o cambia los filtros de búsqueda.')}</div></section>`;}
function templatesView(){const entries=filterTemplates(templateOrder.map(key=>[key,templates[key]]),state.templateQuery||'',state.templateGroup||'all');return customTemplatesView(state)+`<p class="page-description">Elige una base para tu especialidad o crea una plantilla propia para cualquier servicio futuro. Define los criterios de aceptación según el trabajo y la documentación aplicable.</p><div class="template-toolbar"><label class="search-box"><input id="template-search" aria-label="Buscar plantilla o servicio" placeholder="Buscar servicio, equipo o especialidad" value="${e(state.templateQuery||'')}"></label><label class="field"><span>Especialidad</span><select id="template-group">${Object.entries(specialtyGroups).map(([key,label])=>`<option value="${key}" ${(state.templateGroup||'all')===key?'selected':''}>${label}</option>`).join('')}</select></label></div><p class="muted">${entries.length} bases disponibles con este filtro. Las plantillas propias aparecen arriba.</p><div class="template-grid">${entries.map(([key,t])=>`<button class="template-card" data-action="create" data-template="${key}"><span class="template-symbol">${e(t.icon)}</span><span class="template-type">${key==='proposal'?'COMERCIAL':'TÉCNICO'}</span><h2>${e(t.label)}</h2><p>${e(t.description)}</p><span class="template-link">Usar plantilla ${icon('arrow')}</span></button>`).join('')||'<p>No hay bases con estos filtros. Prueba otro término o crea una plantilla propia.</p>'}</div>`;}
function companiesView(){const c=state.companyEdit||company();if(!c)return '';return `<div class="settings-grid"><aside class="panel company-list"><div class="panel-heading"><h2>Mis empresas</h2><button class="icon-btn" data-action="company-new" aria-label="Agregar empresa">${icon('plus')}</button></div>${state.companies.map(x=>`<button data-action="company-edit" data-id="${x.id}" class="company-option ${x.id===c.id?'active':''}"><span>${e((x.tradeName||x.name||'ME').slice(0,2).toUpperCase())}</span><div><b>${e(x.tradeName||x.name||'Empresa sin nombre')}</b><small>${e(x.taxId||'Identificación pendiente')}</small></div></button>`).join('')}<p class="muted">Cada informe conserva los datos de la empresa con los que fue emitido.</p></aside><section class="panel settings-panel"><div class="panel-heading"><div><h2>Identidad de la empresa</h2><p>Esta información aparecerá en tus documentos.</p></div><button class="btn primary" data-action="company-save">Guardar empresa</button></div><div class="logo-editor"><div id="company-logo">${safeImage(c.logo)?`<img src="${safeImage(c.logo)}" alt="Logo">`:icon('building')}</div><div><b>Logo corporativo</b><p>PNG, JPG o WebP · Se conserva la proporción.</p><label class="btn secondary small">Seleccionar logo<input id="logo-file" type="file" accept="image/png,image/jpeg,image/webp" hidden></label><button class="text-btn" data-action="logo-remove">Quitar</button></div></div><div class="form-grid">${field('Razón social','name',c.name,{required:true})}${field('Nombre comercial','tradeName',c.tradeName)}${field('RUT / identificación fiscal','taxId',c.taxId)}${field('Correo','email',c.email,{type:'email'})}${field('Teléfono / WhatsApp','phone',c.phone)}${field('Sitio web','website',c.website)}${field('Dirección','address',c.address,{wide:true})}${field('Ciudad','city',c.city)}${field('País','country',c.country)}${field('Color principal','color',c.color,{type:'color'})}${field('Color de acento','accent',c.accent,{type:'color'})}${field('Moneda de las propuestas','currency',c.currency,{options:['CLP','USD','EUR','PEN','COP','MXN','PYG','ARS']})}${field('Texto del pie de página','footer',c.footer,{wide:true,type:'textarea',placeholder:'Servicios, dirección u otra información corporativa.'})}</div></section></div>`;}
function syncView(){return `<div class="settings-grid"><section class="panel settings-panel"><div class="panel-heading"><div><h2>Tu información, conectada</h2><p>Los cambios se guardan primero en este dispositivo.</p></div>${icon('cloud')}</div><div class="sync-status-card"><span class="connection-dot"></span><div><b>${e(syncState.message)}</b><p>${syncState.lastSync?'Última sincronización: '+new Date(syncState.lastSync).toLocaleString('es-CL'):'Se reintenta al recuperar conexión, abrir la app y mientras permanece activa.'}</p></div></div>${syncState.user?`<div class="account-card"><b>${e(syncState.user.email)}</b><span>Espacio: ${e(syncState.user.workspaceId.slice(0,8))}</span><button class="btn primary" data-action="sync-now">${icon('cloud')} Sincronizar ahora</button><button class="text-btn" data-action="logout">Cerrar sesión</button>${syncState.user.role==='admin'?'<button class="text-btn" data-action="users">Administrar usuarios</button>':''}</div>`:`<div class="notice">${syncState.configured?'Inicia sesión con tu cuenta para sincronizar este dispositivo.':'El modo offline ya está disponible. Para sincronizar, publica el servidor y configura D1 y R2 siguiendo la guía incluida.'}</div><div class="form-grid"><label class="field wide"><span>Correo de acceso</span><input id="login-email" type="email" autocomplete="username"></label><label class="field wide"><span>Contraseña</span><input id="login-password" type="password" autocomplete="current-password"></label><details class="wide"><summary>Primer acceso del administrador</summary><p class="muted">Usa el código de instalación configurado como SETUP_TOKEN en Cloudflare. No se guarda en el dispositivo.</p><label class="field"><span>Código de instalación</span><input id="setup-token" type="password" autocomplete="off"></label></details><button class="btn primary" data-action="login">Conectar dispositivo</button></div>`}<div class="feature-list"><p>${icon('shield')} Los conflictos se revisan antes de sobrescribir.</p><p>${icon('file')} Los documentos emitidos conservan su versión.</p><p>${icon('clock')} El guardado local funciona sin internet.</p></div></section><aside class="side-panels"><section class="panel"><div class="panel-heading"><h2>Respaldo y recuperación</h2></div><p class="muted">Descarga una copia con informes, empresas, catálogos, plantillas, evidencias y firmas. La importación combina registros nuevos y conserva los existentes.</p><button class="btn secondary full" data-action="backup">${icon('download')} Descargar respaldo</button><button class="btn secondary full" data-action="import">Importar respaldo</button><button class="text-btn" data-action="persist-storage">Solicitar almacenamiento persistente</button></section><section class="panel"><div class="panel-heading"><h2>Conflictos pendientes</h2></div><div id="conflicts-list"><p class="muted">Comprobando…</p></div></section><section class="panel"><h2>Aplicación instalada</h2><p class="muted">El contenido se guarda offline después de la primera carga completa. Las nuevas versiones se descargan y se aplican cuando guardas tu trabajo.</p><button class="btn secondary" data-action="install">Instalar aplicación</button><button class="text-btn" data-action="check-update">Buscar actualización</button></section></aside></div>${recoveryPanel()}`;}
function diagnosticsView(){const online=navigator.onLine,logged=!!syncState.user,checked=online&&!!syncState.serverReachable,capabilities=syncState.capabilities;return `<section class="hero diagnostics-hero"><div class="hero-copy"><span class="hero-kicker"><i></i> PUESTA EN MARCHA</span><h2>Conoce el estado de <em>cada servicio.</em></h2><p>Comprueba la preparación de SOLIS antes de salir a terreno. Las conexiones detectadas se separan de las pruebas reales.</p><button class="btn light" data-action="diagnostics-refresh">Actualizar comprobaciones ${icon('arrow')}</button></div></section><div class="stats-grid">${[['cloud',online?'Con conexión':'Sin internet','Conectividad'],['shield',logged?'Sesión iniciada':'Sin sesión','Cuenta'],['file',state.reports.filter(r=>r.companyId===company()?.id&&r._sync?.dirty).length+' pendientes','Cambios locales'],['camera',state.reports.filter(r=>r.companyId===company()?.id).reduce((n,r)=>n+(r.photos?.length||0),0)+' fotografías','Evidencias locales']].map(([ic,n,l])=>`<article class="stat-card"><span class="stat-icon">${icon(ic)}</span><h3>${e(l)}</h3><b>${e(n)}</b><p>Estado actual del dispositivo</p></article>`).join('')}</div><div class="settings-grid"><section class="panel"><div class="panel-heading"><div><h2>Servicios y vinculaciones</h2><p>Comprueba estos nombres en Workers & Pages → solis-informes → Settings.</p></div></div>${[['DB / D1','Base de datos y sincronización','Binding esperado: DB.','El servidor declara si D1 y R2 están vinculados. La sincronización real requiere sesión.'],['BUCKET / R2','Fotografías y anexos','Binding esperado: BUCKET.','El servidor declara si D1 y R2 están vinculados. Los archivos locales se conservan hasta confirmar su subida.'],['AI','Redacción, consultas y transcripción','Workers AI con binding AI.','La prueba real requiere iniciar sesión e internet.'],['BROWSER','PDF desde el servidor','Browser Run con binding BROWSER.','La impresión local sigue disponible sin conexión.'],['Correo','Entrega desde la plataforma','Secrets RESEND_API_KEY y EMAIL_FROM.','El envío debe probarse con un destinatario controlado.']].map(([name,title,sub,desc],i)=>{const configured=i<2?syncState.configured:capabilities[['','','ai','pdf','email'][i]],ready=checked&&configured;return `<article class="service-row"><div class="service-state ${ready?'ok':'pending'}">${ready?'✓':'!'}</div><div><b>${e(title)}</b><p>${e(sub)}</p><small>${e(desc)}</small></div><span class="pill ${ready?'green':'amber'}">${!checked?'Sin comprobar':configured?'Declarado por servidor':'Sin configurar'}</span></article>`;}).join('')}</section><aside class="side-panels"><section class="panel"><h2>Antes de ir a terreno</h2><p class="muted">Descarga la aplicación, abre los informes que necesitarás y verifica que las fotografías estén disponibles en este dispositivo.</p><button class="btn secondary full" data-action="nav" data-view="sync">Abrir centro de sincronización</button><button class="btn secondary full" data-action="backup">Descargar respaldo</button></section><section class="panel"><h2>Pruebas seguras</h2><p class="muted">No se enviará contenido real del cliente. Para probar IA, utiliza un informe de prueba y confirma la sesión antes de solicitar una propuesta.</p><button class="btn primary full" data-action="nav" data-view="team">Abrir equipo y servicios</button></section></aside></div>`;}
function editorView(){const r=state.report;if(!r)return '';const locked=r.status!=='Borrador',errors=validateReport(r);return `<div class="editor-toolbar"><button class="text-btn" data-action="nav" data-view="reports">← Informes</button><div class="editor-save"><span id="save-status">${locked?'Control documental · edición bloqueada':'Todos los cambios guardados'}</span>${status(r)}<button class="btn secondary small" data-action="preview">Vista previa</button>${locked?(r.status==='Emitido'?'<button class="btn primary small" data-action="revision">Crear revisión</button>':'<button class="btn secondary small" data-action="lifecycle" data-status="Borrador">Devolver a borrador</button>'):'<button class="btn primary small" data-action="save">Guardar</button>'}<button class="btn secondary small" data-action="share">${icon('share')} Compartir</button></div></div>${workflowSummary(r)}<div class="editor-grid"><section class="panel editor-panel"><div class="editor-tabs" role="tablist">${tabs.map((t,i)=>`<button role="tab" aria-selected="${state.tab===i}" class="${state.tab===i?'active':''}" data-action="tab" data-index="${i}"><span>${i+1}</span>${t}</button>`).join('')}</div><div class="editor-body"><div class="section-heading"><div><span class="eyebrow">${e(templates[r.template].label)}</span><h2>${tabs[state.tab]}</h2></div>${state.tab===4&&!locked?`<button class="btn ai-btn" data-action="ai">${icon('spark')} Asistente de redacción</button>`:''}</div>${locked?`<div class="notice">Estado ${e(r.status)} · La edición está bloqueada. Usa el control documental para devolverlo o crear una revisión.</div>`:''}<div id="workflow-notice"></div>${editorTab(r)}${reportEnterpriseTools(r)}</div><div class="editor-bottom"><button class="btn secondary" data-action="tab" data-index="${Math.max(0,state.tab-1)}" ${state.tab===0?'disabled':''}>Anterior</button><span>Paso ${state.tab+1} de ${tabs.length}</span>${state.tab<tabs.length-1?`<button class="btn primary" data-action="tab" data-index="${state.tab+1}">Continuar ${icon('arrow')}</button>`:''}</div></section><aside class="editor-aside"><section class="panel document-summary"><span class="eyebrow">TU DOCUMENTO</span><span class="report-symbol">${templates[r.template].icon}</span><h3>${e(r.title)}</h3><p>${e(r.customerCompany||'Cliente por definir')}</p><div class="summary-line"><span>Empresa emisora</span><b>${e(r.companySnapshot?.tradeName||r.companySnapshot?.name||'Sin configurar')}</b></div><div class="summary-line"><span>Revisión</span><b>${r.revision||0}</b></div><div class="summary-line"><span>Fotografías</span><b>${r.photos.length}</b></div><div class="summary-line"><span>Estado local</span><b id="editor-sync-label">${e(labelSync(r))}</b></div><button class="btn secondary full" data-action="preview">${icon('file')} Vista previa</button><button class="btn secondary full" data-action="pdf">${icon('download')} Descargar PDF</button><button class="text-btn" data-action="print">Imprimir / PDF sin conexión</button></section><section class="panel readiness"><h3>Revisión de contenido</h3><p id="readiness-count">${errors.length?`${errors.length} punto${errors.length===1?'':'s'} por completar`:'Contenido listo para emitir'}</p><div id="readiness-items">${errors.slice(0,6).map(x=>`<span>○ ${e(x)}</span>`).join('')||'<span class="green-text">✓ Campos esenciales completos</span>'}</div></section></aside></div>`;}
function editorTab(r){const eq=r.equipment;switch(state.tab){case 0:return `${reportCatalogSelectors(state,r,'service')}<div class="form-grid">${field('Título del documento','title',r.title,{wide:true,required:true})}${field('Folio','folio',r.folio,{required:true})}${field('Fecha del servicio','serviceDate',r.serviceDate,{type:'date',required:true})}${field('OT / referencia','workOrder',r.workOrder)}${field('Tipo de intervención','maintenanceType',r.maintenanceType,{options:templates[r.template].serviceOptions})}${field('Empresa cliente','customerCompany',r.customerCompany,{required:true})}${field('Contacto / receptor','customerName',r.customerName)}${field('Correo del cliente','customerEmail',r.customerEmail,{type:'email'})}${field('WhatsApp del cliente','customerPhone',r.customerPhone,{placeholder:'Código de país y número'})}${field('Ubicación / instalación','site',r.site,{wide:true,required:true})}${field('Responsable del informe','technician',r.technician,{required:true})}${field('Revisor','reviewer',r.reviewer)}${field('Identificación del contacto','customerId',r.customerId)}${field('Cargo','customerRole',r.customerRole)}</div>`;
 case 1:return `${reportCatalogSelectors(state,r,'equipment')}<p class="muted">Identifica el equipo principal y agrega otros equipos cuando la visita abarque varios activos.</p><div class="form-grid">${[['Tipo de equipo / sistema','equipmentType'],['TAG / activo','assetTag'],['Marca','brand'],['Modelo','model'],['Serie','serial'],['Ubicación específica','location'],['Servicio / proceso','service'],['Rango / capacidad','range'],['Señal','signal'],['Alimentación','supply'],['Protocolo','protocol']].map(([l,k])=>field(l,'equipment.'+k,eq[k])).join('')}${r.template==='generator'?field('Potencia (kVA)','equipment.ratedPower',eq.ratedPower,{type:'number'})+field('Tensión nominal (V)','equipment.ratedVoltage',eq.ratedVoltage,{type:'number'})+field('Horómetro actual (h)','schedule.hourmeter',r.schedule.hourmeter,{type:'number'})+field('Intervalo de mantenimiento (h)','schedule.interval',r.schedule.interval,{type:'number'})+field('Uso promedio (h/día)','schedule.avgDailyHours',r.schedule.avgDailyHours,{type:'number'}):''}</div><div class="subheading"><h3>Otros equipos / sistemas</h3>${addButton('asset-add','Agregar equipo')}</div>${r.assets.map((a,i)=>`<div class="repeat-card"><div class="repeat-heading"><b>Equipo ${i+2}</b>${removeButton('asset-remove',i)}</div><div class="form-grid">${otherEquipmentSelector(state,r,a,i)}${[['TAG','tag'],['Equipo','name'],['Marca / modelo','model'],['Serie','serial'],['Observaciones','notes']].map(([l,k])=>field(l,`assets.${i}.${k}`,a[k])).join('')}</div></div>`).join('')}`;
 case 2:return `<p class="muted">Registra únicamente lecturas medidas. Indica la referencia técnica cuando corresponda.</p><div class="editable-rows">${r.measurements.map((m,i)=>`<div class="measurement-row">${field('Parámetro',`measurements.${i}.label`,m.label)}${field('Lectura',`measurements.${i}.value`,m.value)}${field('Unidad',`measurements.${i}.unit`,m.unit)}${field('Referencia',`measurements.${i}.reference`,m.reference)}${removeButton('measurement-remove',i)}</div>`).join('')}</div>${addButton('measurement-add','Agregar medición')}`;
 case 3:return `<div class="inspection-head"><p class="muted">Marca cada verificación y explica los hallazgos.</p><span class="pill neutral">${e(inspectionResult(r.checklist))}</span></div>${r.checklist.map((item,i)=>`<div class="inspection-row">${field('Punto de inspección',`checklist.${i}.label`,item.label)}${field('Condición',`checklist.${i}.condition`,item.condition,{options:['','Conforme','Atención','No conforme','No aplica']})}${field('Observación',`checklist.${i}.notes`,item.notes,{placeholder:'Detalle, limitación o evidencia'})}${removeButton('check-remove',i)}</div>`).join('')}${addButton('check-add','Agregar verificación')}`;
 case 4:return `<div class="form-grid">${[['Objetivo','objective','Qué busca determinar o resolver este informe.'],['Alcance','scope','Trabajos, equipos y límites de la intervención.'],['Exclusiones y limitaciones','exclusions','Aspectos que no fueron evaluados o ejecutados.'],['Condición inicial','initialCondition','Situación encontrada antes del trabajo.'],['Actividades y pruebas realizadas','workPerformed','Describe únicamente lo que se ejecutó.'],['Hallazgos / diagnóstico','diagnosis','Separa las evidencias de las hipótesis.'],['Materiales y repuestos','materials','Cantidades, descripción y referencias.'],['Observaciones','observations','Condiciones relevantes o información pendiente.'],['Conclusiones','conclusions','Resultado sustentado en los datos registrados.'],['Recomendaciones','recommendations','Acciones propuestas para revisión del responsable.']].map(([l,k,p])=>field(l,k,r[k],{type:'textarea',wide:true,placeholder:p,required:['objective','scope','conclusions'].includes(k)})).join('')}</div>${(r.customSections||[]).map((section,i)=>field(section.title,`customSections.${i}.content`,section.content,{type:'textarea',wide:true,required:section.required})).join('')}${designerEditor(r,field)}${r.template==='proposal'?proposalEditor(r):''}<div class="subheading"><h3>Plan de acciones</h3>${addButton('action-add','Agregar acción')}</div>${r.actions.map((a,i)=>`<div class="repeat-card"><div class="repeat-heading"><b>Acción ${i+1}</b>${removeButton('action-remove',i)}</div><div class="form-grid">${field('Acción',`actions.${i}.description`,a.description,{wide:true})}${field('Prioridad',`actions.${i}.priority`,a.priority,{options:['Alta','Media','Baja']})}${field('Responsable',`actions.${i}.owner`,a.owner)}${field('Fecha objetivo',`actions.${i}.dueDate`,a.dueDate,{type:'date'})}${field('Estado',`actions.${i}.status`,a.status,{options:['Pendiente','En curso','Completada']})}</div></div>`).join('')}`;
 case 5:return `${attachmentEditor(r)}<label class="upload-area">${icon('camera')}<b>Agrega evidencias de tu trabajo</b><span>Toma fotografías o selecciona archivos · Hasta 24 imágenes</span><input id="photos-input" type="file" accept="image/png,image/jpeg,image/webp" multiple ${r.status!=='Borrador'?'disabled':''}><span class="btn secondary">Cámara / galería</span></label><div class="photo-grid">${r.photos.map((p,i)=>`<figure class="photo-card"><div><img src="${safeImage(p.dataUrl)}" alt="Evidencia ${i+1}">${removeButton('photo-remove',i)}<button class="photo-annotate" data-action="photo-annotate" data-index="${i}" ${r.status!=='Borrador'?'disabled':''}>Marcar evidencia</button></div><figcaption><b>Figura ${i+1}</b>${field('Descripción',`photos.${i}.caption`,p.caption,{type:'textarea',placeholder:'Qué muestra la imagen y por qué es relevante.'})}${field('TAG / hallazgo relacionado',`photos.${i}.tag`,p.tag||'')}</figcaption></figure>`).join('')}</div>`;
 case 6:return findingsEditor(r,field);
 case 7:return `<div class="form-grid">${field('Resultado del servicio','result',r.result,{options:['No evaluado','Conforme','Con observaciones','No conforme','Inspección parcial']})}<div class="field"><span>Resultado según checklist</span><div class="readonly-value">${e(inspectionResult(r.checklist))}</div></div></div><div class="signature-grid">${signaturePad('technicianSignature','Firma del responsable',r.technicianSignature,r.technician)}${signaturePad('clientSignature','Recepción del cliente',r.clientSignature,r.customerName)}</div><p class="muted">Las firmas son opcionales. Un documento emitido queda bloqueado; los cambios posteriores se realizan mediante una nueva revisión.</p><div class="lifecycle"><div><h3>Control documental</h3><p>Revisa la vista previa antes de emitir.</p></div>${r.status!=='Emitido'?`<div>${r.status==='En revisión'?'<button class="btn secondary" data-action="review-register">Registrar revisión técnica</button>':''}<button class="btn secondary" data-action="lifecycle" data-status="En revisión">Enviar a revisión</button><button class="btn secondary" data-action="lifecycle" data-status="Aprobado">Aprobar</button><button class="btn primary" data-action="lifecycle" data-status="Emitido">Emitir documento</button></div>`:'<span class="pill green">Versión emitida</span>'}</div><details class="history"><summary>Historial del documento (${r.history.length})</summary>${r.history.slice().reverse().map(h=>`<p><b>${e(h.action)}</b><small>${new Date(h.at).toLocaleString('es-CL')}</small></p>`).join('')}</details>`;
 }}
function addButton(action,label){return state.report?.status!=='Borrador'?'':`<button class="btn secondary small" data-action="${action}">${icon('plus')}${label}</button>`;}
function removeButton(action,index){return state.report?.status!=='Borrador'?'':`<button class="icon-btn remove" data-action="${action}" data-index="${index}" aria-label="Quitar elemento">${icon('x')}</button>`;}
function proposalEditor(r){const total=proposalTotals(r),c=r.companySnapshot;return `<div class="subheading"><h3>Presupuesto de la propuesta</h3>${addButton('item-add','Agregar partida')}</div>${r.proposalItems.map((p,i)=>`<div class="repeat-card"><div class="repeat-heading"><b>Partida ${i+1}</b>${removeButton('item-remove',i)}</div><div class="form-grid">${field('Descripción',`proposalItems.${i}.description`,p.description,{wide:true})}${field('Cantidad',`proposalItems.${i}.quantity`,p.quantity,{type:'number'})}${field('Unidad',`proposalItems.${i}.unit`,p.unit)}${field('Precio unitario',`proposalItems.${i}.price`,p.price,{type:'number'})}</div></div>`).join('')}<div class="form-grid">${field('Impuesto (%)','taxRate',r.taxRate,{type:'number'})}${field('Vigencia (días)','proposalValidity',r.proposalValidity,{type:'number'})}${field('Plazo de ejecución','proposalDeadline',r.proposalDeadline)}${field('Condiciones comerciales','proposalTerms',r.proposalTerms,{wide:true,type:'textarea'})}</div><p class="proposal-total">Total estimado: <b id="proposal-total">${e(money(total.total,c?.currency))}</b></p>`;}
function signaturePad(key,label,image,name){return `<div class="signature-card"><div><b>${label}</b>${state.report.status==='Borrador'?`<button class="text-btn" data-action="signature-clear" data-key="${key}">Limpiar</button>`:''}</div><canvas data-signature="${key}" width="760" height="220" aria-label="${label}"></canvas><small>${e(name||'Nombre por completar')}</small><img hidden data-signature-src="${key}" src="${safeImage(image)}" alt=""></div>`;}
function setPath(target,path,value){const keys=path.split('.');let obj=target;for(const key of keys.slice(0,-1))obj=obj[key];obj[keys.at(-1)]=value;}
function markDirty(){dirty=true;clearTimeout(saveTimer);const el=$('#save-status');if(el)el.textContent='Guardando cambios…';saveTimer=setTimeout(()=>persist(),350);}
const persist=serializeSaves(async()=>{
 clearTimeout(saveTimer);if(!dirty||!state.report||state.report.status!=='Borrador')return;
 const current=state.report,snapshot=structuredClone(current);dirty=false;savePending++;
 try{
  const saved=await db.saveEntity('reports',snapshot);
  if(state.report===current){current._sync=saved._sync;current.updatedAt=saved.updatedAt;}
  const el=$('#save-status');if(el)el.textContent=dirty?'Guardando cambios…':'Guardado en este dispositivo';await reload();updateReadiness();
 }catch(error){
  if(error.code==='LOCAL_CHANGED'&&error.recoveryId&&state.report===current){
   if(dirty)await db.updateDraftRecovery(error.recoveryId,current);
   dirty=false;const latest=await db.get('reports',current.id);if(latest)state.report=normalizeReport(latest,company());await reload();render();
   modal('Tu edición está resguardada',`<p>Otro cambio se guardó antes en este dispositivo. El informe muestra ahora la versión guardada y tu edición se conservó como una copia independiente.</p><div class="modal-actions"><button class="btn primary" data-action="recovery-view" data-id="${e(error.recoveryId)}">Ver mi copia</button><button class="btn secondary" data-action="close-modal">Continuar con el informe guardado</button></div>`);
  }else dirty=true;
  toast(error.message,true);throw error;
 }finally{savePending--;}
});
function updateReadiness(){if(!state.report)return;const errors=validateReport(state.report);const count=$('#readiness-count'),items=$('#readiness-items');if(count)count.textContent=errors.length?`${errors.length} puntos por completar`:'Contenido listo para emitir';if(items)items.innerHTML=errors.slice(0,6).map(x=>`<span>○ ${e(x)}</span>`).join('')||'<span class="green-text">✓ Campos esenciales completos</span>';}
function bindEditor(){document.querySelectorAll('[data-field]').forEach(input=>{input.addEventListener('input',()=>{if(state.report.status!=='Borrador')return;setPath(state.report,input.dataset.field,input.value);markDirty();const total=$('#proposal-total');if(total)total.textContent=money(proposalTotals(state.report).total,state.report.companySnapshot?.currency);});});bindSignatures();}
function bindCompany(){state.companyEdit=structuredClone(state.companyEdit||company());document.querySelectorAll('[data-field]').forEach(input=>input.addEventListener('input',()=>setPath(state.companyEdit,input.dataset.field,input.value)));}
function bindSignatures(){document.querySelectorAll('canvas[data-signature]').forEach(canvas=>{const key=canvas.dataset.signature,ctx=canvas.getContext('2d'),image=state.report[key];if(image){const im=new Image();im.onload=()=>ctx.drawImage(im,0,0,canvas.width,canvas.height);im.src=image;}if(state.report.status!=='Borrador')return;let drawing=false;const point=ev=>{const box=canvas.getBoundingClientRect();return [(ev.clientX-box.left)*canvas.width/box.width,(ev.clientY-box.top)*canvas.height/box.height];};canvas.addEventListener('pointerdown',ev=>{drawing=true;canvas.setPointerCapture(ev.pointerId);ctx.beginPath();ctx.moveTo(...point(ev));ctx.lineWidth=3;ctx.lineCap='round';ctx.strokeStyle='#173b50';});canvas.addEventListener('pointermove',ev=>{if(drawing){ctx.lineTo(...point(ev));ctx.stroke();}});const end=()=>{if(!drawing)return;drawing=false;state.report[key]=canvas.toDataURL('image/png');markDirty();};canvas.addEventListener('pointerup',end);canvas.addEventListener('pointercancel',end);});}
function modal(title,body,{wide=false}={}){$('#modal-root').innerHTML=`<div class="modal-backdrop"><section class="modal ${wide?'modal-wide':''}" role="dialog" aria-modal="true" aria-label="${e(title)}"><header><h2>${e(title)}</h2><button class="icon-btn" data-action="close-modal" aria-label="Cerrar">${icon('x')}</button></header><div class="modal-body">${body}</div></section></div>`;const focus=$('#modal-root input,#modal-root button');focus?.focus();}
function closeModal(){clearRecoveryPreview();stopCapture();$('#modal-root').innerHTML='';}
async function createReport(key,record=null,equipmentId=''){await persist();if(!company()?.name){toast('Primero completa la razón social de tu empresa.');state.view='companies';render();return;}key=record?.baseTemplate||key;const folio=await db.nextFolio(templates[key].prefix),r=record?createFromTemplate(record,company(),folio):newReport(key,company(),folio);if(equipmentId)selectEquipment(r,state.equipment.find(a=>a.id===equipmentId),state.sites,state.customers);state.report=await db.saveEntity('reports',r);await reload();state.view='editor';state.tab=0;closeModal();render();}
async function openReport(id){await persist();const r=await db.get('reports',id);if(!r||r._sync?.deleted)return;state.report=normalizeReport(r,company());state.companyId=r.companyId;state.view='editor';state.tab=0;closeModal();render();}
async function navigate(view){await persist();state.view=view;state.companyEdit=null;render();window.scrollTo(0,0);}
async function preview(print=false){await persist();modal(print?'Imprimir documento':'Vista previa del documento',`<div class="preview-tools"><p>Formato A4 · Se conserva la proporción de las evidencias.</p><button class="btn primary" data-action="print-frame">Imprimir / Guardar como PDF</button></div><iframe id="report-preview" title="Vista previa del informe" sandbox="allow-same-origin allow-modals"></iframe>`,{wide:true});const frame=$('#report-preview');frame.srcdoc=renderDocument(state.report);if(print)frame.addEventListener('load',()=>{frame.contentWindow.focus();frame.contentWindow.print();},{once:true});}
async function downloadPdf(){await persist();if(!navigator.onLine||!syncState.user||!syncState.capabilities.pdf){await preview(true);toast('PDF offline: selecciona Guardar como PDF en la impresión.');return null;}toast('Preparando PDF…');const res=await fetch('/api/pdf',{method:'POST',headers:{'Content-Type':'application/json','X-Solis-Client':'4'},body:JSON.stringify({report:await uploadAssets(dataForSync(state.report),state.report.companyId)}),credentials:'same-origin'});if(!res.ok){const error=await res.json();throw new Error(error.error||'No se pudo generar el PDF');}const blob=await res.blob();download(blob,`${state.report.folio}_Rev${state.report.revision}.pdf`);return blob;}
function download(blob,name){const url=URL.createObjectURL(blob),a=document.createElement('a');a.href=url;a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(url),60000);}
async function shareDialog(){await persist();const r=state.report;modal('Compartir informe',`<div class="share-summary">${icon('share')}<div><b>${e(r.title)}</b><p>${e(r.folio)} · Rev. ${r.revision}</p></div></div><p class="muted">El PDF se puede compartir desde el menú del dispositivo. Para enviar un enlace privado, el documento debe estar emitido y sincronizado.</p><div class="share-buttons"><button class="btn secondary" data-action="native-share">${icon('share')} Compartir archivo PDF</button><button class="btn secondary" data-action="pdf">${icon('download')} Descargar PDF</button><button class="btn primary" data-action="share-link">Crear enlace privado · 7 días</button></div><div id="share-result"></div>`);}
async function createShare(){const r=state.report;if(r.status!=='Emitido')throw new Error('Emite el documento antes de crear un enlace de entrega.');await synchronize();const latest=await db.get('reports',r.id);if(latest._sync?.dirty||latest._sync?.conflict)throw new Error('El informe debe estar sincronizado y sin conflictos.');const result=await api('/api/shares',{reportId:r.id,expiresDays:7});$('#share-result').innerHTML=`<div class="notice">Cualquier persona que reciba este enlace podrá consultar esta versión durante 7 días.</div><label class="field"><span>Enlace privado</span><input id="share-url" readonly value="${e(result.url)}"></label><div class="share-buttons"><button class="btn secondary" data-action="copy-link">Copiar enlace</button><a class="btn primary" target="_blank" rel="noopener" href="https://wa.me/${encodeURIComponent((r.customerPhone||'').replace(/\D/g,''))}?text=${encodeURIComponent(`Hola, comparto ${r.title} (${r.folio}): ${result.url}`)}">WhatsApp</a><a class="btn secondary" href="mailto:${encodeURIComponent(r.customerEmail||'')}?subject=${encodeURIComponent(r.title+' · '+r.folio)}&body=${encodeURIComponent('Hola,\n\nComparto el informe: '+result.url+'\n\nSaludos,\n'+(r.companySnapshot?.name||''))}">Abrir correo</a></div><details><summary>Enviar correo desde la plataforma</summary><p class="muted">Requiere configurar el proveedor de correo en Cloudflare.</p><label class="field"><span>Destinatario</span><input id="email-to" type="email" value="${e(r.customerEmail)}"></label><button class="btn primary" data-action="send-email" data-token="${result.token}">Enviar enlace por correo</button></details><button class="text-btn danger" data-action="revoke-share" data-token="${result.token}">Revocar este enlace</button>`;}
async function aiDialog(){await persist();modal('Asistente de redacción',`<p class="muted">El asistente trabaja con las notas, actividades y mediciones de este informe. Revisa cada propuesta antes de incorporarla.</p><div class="form-grid"><label class="field"><span>Sección de destino</span><select id="ai-field">${[['workPerformed','Actividades realizadas'],['diagnosis','Diagnóstico / hallazgos'],['conclusions','Conclusiones'],['recommendations','Recomendaciones'],['objective','Objetivo'],['scope','Alcance']].map(([v,l])=>`<option value="${v}">${l}</option>`).join('')}</select></label><label class="field"><span>Acción</span><select id="ai-action"><option value="rewrite">Mejorar redacción</option><option value="draft">Preparar borrador</option><option value="review">Revisar información faltante</option></select></label></div><button class="btn ai-btn" data-action="ai-generate">${icon('spark')} Generar propuesta</button><div id="ai-result"></div>`);}
async function generateAi(){if(!navigator.onLine||!syncState.user)throw new Error('Conéctate e inicia sesión para usar el asistente.');const target=$('#ai-field').value,action=$('#ai-action').value,r=state.report;$('#ai-result').innerHTML='<p class="muted">Preparando una propuesta…</p>';try{const result=await api('/api/ai',{target,action,context:{companyId:r.companyId,template:r.template,title:r.title,objective:r.objective,scope:r.scope,workPerformed:r.workPerformed,diagnosis:r.diagnosis,observations:r.observations,conclusions:r.conclusions,recommendations:r.recommendations,measurements:r.measurements,checklist:r.checklist,findings:r.findings}});$('#ai-result').innerHTML=`<label class="field"><span>Propuesta del asistente · Requiere revisión</span><textarea id="ai-output" rows="12">${e(result.text)}</textarea></label>${action==='review'?'<p class="muted">Esta revisión no se incorpora automáticamente al informe.</p>':`<button class="btn primary" data-action="ai-apply" data-target="${target}">Usar texto revisado</button>`}`;}catch(error){$('#ai-result').innerHTML=`<p class="error-text">${e(error.message)}</p>`;}}
async function renderConflicts(){const list=await db.conflicts(),el=$('#conflicts-list');if(!el)return;el.innerHTML=list.length?list.map(c=>`<div class="conflict-card"><b>${e(c.value.data?.folio||c.value.data?.name||c.value.id)}</b><p>Existen cambios locales y cambios del servidor.</p><button class="btn secondary small" data-action="conflict-view" data-key="${e(c.id)}">Comparar versiones</button></div>`).join(''):'<p class="muted">No hay conflictos pendientes.</p>';}
async function compareConflict(key){const record=await db.get('meta',key);const [,kind,id]=key.split(':'),local=await db.get(kind,id);modal('Comparar cambios',`<p class="muted">Descarga primero un respaldo si necesitas conservar ambas versiones. La elección se aplicará al registro completo.</p><div class="conflict-compare"><div><h3>Este dispositivo</h3><pre>${e(JSON.stringify(local,(k,v)=>typeof v==='string'&&v.startsWith('data:image/')?'[Imagen guardada]':v,2))}</pre></div><div><h3>Servidor</h3><pre>${e(JSON.stringify(record.value.data,(k,v)=>typeof v==='string'&&v.startsWith('data:image/')?'[Imagen guardada]':v,2))}</pre></div></div><div class="share-buttons"><button class="btn secondary" data-action="backup">Descargar respaldo</button><button class="btn primary" data-action="conflict-resolve" data-key="${e(key)}" data-choice="local">${record.value.data?.status==='Emitido'?'Guardar mis cambios como revisión':'Conservar este dispositivo'}</button><button class="btn secondary" data-action="conflict-resolve" data-key="${e(key)}" data-choice="remote">Conservar servidor</button></div>`,{wide:true});}
function updateSyncUI(){const el=$('#sync-label');if(el)el.textContent=syncState.message;document.querySelectorAll('.sync-indicator .connection-dot').forEach(x=>x.className='connection-dot '+(['error','conflict','offline','blocked'].includes(syncState.status)?'warning':''));}
async function imageData(file,{logo=false}={}){if(!['image/png','image/jpeg','image/webp'].includes(file.type)||file.size>20000000)throw new Error('Selecciona PNG, JPG o WebP de hasta 20 MB.');const image=typeof createImageBitmap==='function'?await createImageBitmap(file):await new Promise((resolve,reject)=>{const url=URL.createObjectURL(file),img=new Image();img.onload=()=>{URL.revokeObjectURL(url);resolve(img);};img.onerror=()=>{URL.revokeObjectURL(url);reject(new Error('No se pudo abrir la imagen.'));};img.src=url;});const max=logo?650:1400,scale=Math.min(1,max/Math.max(image.width,image.height)),canvas=document.createElement('canvas');canvas.width=Math.round(image.width*scale);canvas.height=Math.round(image.height*scale);const ctx=canvas.getContext('2d');if(!logo){ctx.fillStyle='#fff';ctx.fillRect(0,0,canvas.width,canvas.height);}ctx.drawImage(image,0,0,canvas.width,canvas.height);image.close?.();let data=canvas.toDataURL(logo?'image/png':'image/jpeg',.72);if(data.length>750000){data=canvas.toDataURL('image/jpeg',.55);}if(data.length>900000)throw new Error('La imagen es demasiado compleja. Reduce su tamaño antes de agregarla.');return data;}
function enterpriseContext(){return {state,db,modal,closeModal,reload,render,toast,company,createReport,openReport,download,markDirty,persist};}
async function handleAction(button){const a=button.dataset.action;
 if(await handleRecoveryAction(button,enterpriseContext()))return;
 if(await handleAccountAction(button,enterpriseContext()))return;
 if(await handleEnterpriseAction(button,enterpriseContext()))return;
 if(await handleWorkspaceAction(button,{state,db,modal,closeModal,reload,render,toast,createReport,sync:synchronize}))return;
 if(a==='finding-add'||a==='finding-remove'){if(state.report.status!=='Borrador')return;if(a==='finding-add')state.report.findings.push({id:uid(),title:'',description:'',priority:'Media',recommendation:'',owner:'',dueDate:'',status:'Pendiente',resolution:'',equipmentTag:state.report.equipment.assetTag,photoIds:[]});else state.report.findings.splice(Number(button.dataset.index),1);markDirty();await persist();render();return;}
 if(a==='close-modal'){closeModal();return;}if(a==='menu'){$('#sidebar').classList.toggle('open');return;}
 if(a==='home'||a==='nav'){await navigate(button.dataset.view||'dashboard');return;}
 if(a==='new'){await persist();state.view='templates';render();return;}
 if(a==='create'){await createReport(button.dataset.template);return;}
 if(a==='open'){await openReport(button.dataset.id);return;}
 if(a==='tab'){await persist();state.tab=Number(button.dataset.index);render();return;}
 if(a==='save'){await persist();toast('Cambios guardados en este dispositivo.');return;}
 if(a==='company-new'){state.companyEdit=newCompany();state.view='companies';render();return;}
 if(a==='company-edit'){state.companyEdit=structuredClone(state.companies.find(c=>c.id===button.dataset.id));render();return;}
 if(a==='company-save'){const c=state.companyEdit;if(!c.name.trim())throw new Error('Completa la razón social.');await db.saveEntity('companies',c);state.companyId=c.id;await db.setMeta('activeCompany',c.id);await reload();state.companyEdit=null;render();toast('Empresa guardada. Se usará en los nuevos informes.');void synchronize();return;}
 if(a==='logo-remove'){state.companyEdit.logo='';$('#company-logo').innerHTML=icon('building');return;}
 if(a==='trash'){const deleted=(await db.all('reports',{deleted:true})).filter(r=>r._sync?.deleted&&r.companyId===company()?.id);modal('Papelera',deleted.length?deleted.map(r=>`<div class="conflict-card"><b>${e(r.folio)}</b><p>${e(r.title)}</p><button class="btn secondary small" data-action="restore" data-id="${r.id}">Restaurar informe</button></div>`).join(''):'<p class="muted">La papelera está vacía.</p>');return;}
 if(a==='restore'){const r=await db.get('reports',button.dataset.id);await db.saveEntity('reports',r,{deleted:false});await reload();closeModal();render();toast('Informe restaurado.');return;}
 if(a==='users'){const data=await api('/api/users');modal('Equipo de trabajo',`<p class="muted">Estos usuarios comparten los informes y empresas del mismo espacio.</p>${data.users.map(u=>`<p><b>${e(u.email)}</b> · ${e(u.role)}</p>`).join('')}<hr><h3>Agregar usuario</h3><label class="field"><span>Correo</span><input id="user-email" type="email"></label><label class="field"><span>Contraseña inicial · mínimo 12 caracteres</span><input id="user-password" type="password" autocomplete="new-password"></label><button class="btn primary" data-action="user-create">Crear usuario</button>`);return;}
 if(a==='user-create'){await api('/api/users',{email:$('#user-email').value,password:$('#user-password').value});closeModal();toast('Usuario creado.');return;}
 if(a==='report-menu'){const r=state.reports.find(r=>r.id===button.dataset.id);modal('Opciones del documento',`<p><b>${e(r.folio)}</b> · ${e(r.title)}</p><div class="share-buttons"><button class="btn secondary" data-action="open" data-id="${r.id}">Abrir documento</button><button class="btn secondary" data-action="duplicate" data-id="${r.id}">${icon('copy')} Duplicar como nuevo</button>${r.status!=='Emitido'?`<button class="btn secondary danger" data-action="delete" data-id="${r.id}">Mover a papelera</button>`:''}</div>`);return;}
 if(a==='duplicate'){const original=state.reports.find(r=>r.id===button.dataset.id),r=normalizeReport(structuredClone(original),company());r.id=uid();r.folio=await db.nextFolio(templates[r.template].prefix);r.status='Borrador';r.legacyImported=false;r.revision=0;r.parentId='';r.clientSignature=r.technicianSignature='';r.createdAt=new Date().toISOString();for(const key of ['createdBy','assignedTo','approvedBy','approvedAt','reviewedBy','reviewedAt','issuedBy','issuedAt'])r[key]='';r.schemaVersion=4;delete r._sync;r.history=[{at:r.createdAt,action:'Duplicado como nuevo documento'}];await db.saveEntity('reports',r);await openReport(r.id);return;}
 if(a==='delete'){const r=state.reports.find(r=>r.id===button.dataset.id);if(confirm(`¿Mover ${r.folio} a la papelera? Podrás recuperarlo desde el respaldo o la papelera.`)){await db.saveEntity('reports',r,{deleted:true});await reload();closeModal();render();toast('Informe movido a papelera.');}return;}
 if(a==='revision'){await persist();const original=state.report;const revisions=state.reports.filter(r=>r.folio===original.folio);const next=reviseReport(original);next.revision=Math.max(...revisions.map(r=>r.revision||0))+1;await db.saveEntity('reports',next);await openReport(next.id);return;}
 if(a==='lifecycle'){await persist();const target=button.dataset.status;if(['Aprobado','Emitido'].includes(target)){const errors=validateReport(state.report);if(errors.length)throw new Error('Completa: '+errors.join(', '));}if(target==='Emitido'&&!confirm('Se conservará esta versión y se bloqueará su edición. ¿Emitir documento?'))return;const snapshot=structuredClone(state.report);snapshot.status=target;if(target==='Emitido')snapshot.issuedAt=new Date().toISOString();snapshot.history.push({at:new Date().toISOString(),action:`Estado: ${target}`,by:syncState.user?.email||snapshot.technician});state.report=await db.saveEntity('reports',snapshot);await reload();render();toast('Estado actualizado.');void synchronize();return;}
 if(a==='preview'||a==='print'){await preview(a==='print');return;}if(a==='print-frame'){$('#report-preview')?.contentWindow?.print();return;}
 if(a==='pdf'){await downloadPdf();return;}if(a==='share'){await shareDialog();return;}if(a==='share-link'){await createShare();return;}
 if(a==='copy-link'){await navigator.clipboard.writeText($('#share-url').value);toast('Enlace copiado.');return;}
 if(a==='native-share'){const blob=await downloadPdf();if(!blob)return;const file=new File([blob],`${state.report.folio}.pdf`,{type:'application/pdf'});if(navigator.canShare?.({files:[file]})){await navigator.share({title:state.report.title,files:[file]});}else toast('El PDF está descargado. Adjunta el archivo en WhatsApp o correo.');return;}
 if(a==='send-email'){const email=$('#email-to').value.trim();if(!email)throw new Error('Completa el destinatario.');button.disabled=true;try{await api('/api/email',{token:button.dataset.token,to:email});toast('Correo enviado.');}finally{button.disabled=false;}return;}
 if(a==='revoke-share'){await api('/api/shares/revoke',{token:button.dataset.token});$('#share-result').innerHTML='<p>Enlace revocado.</p>';return;}
 if(a==='diagnostics-refresh'){await checkSession();await reload();render();toast(syncState.serverReachable?'Estado recibido del servidor. Las pruebas de IA, PDF y correo se realizan desde sus funciones.':'No se pudo consultar el servidor. Se muestra el estado local.',!syncState.serverReachable);return;}
 if(a==='photo-annotate'){if(!state.report||state.report.status!=='Borrador')throw new Error('Solo puedes anotar evidencias en borradores.');const idx=Number(button.dataset.index),photo=state.report.photos[idx];if(!photo)throw new Error('No se encontró la fotografía.');modal('Marcar evidencia',`<p class="muted">Dibuja sobre la imagen para señalar una zona. La imagen original se conservará y la versión marcada se agregará como copia anotada al documento.</p><div class="annotation-tools"><label>Color <input id="annotation-color" type="color" value="#e53935"></label><button class="btn secondary small" data-action="annotation-clear">Limpiar marcas</button></div><div class="annotation-canvas-wrap"><canvas id="annotation-canvas"></canvas></div><div class="share-buttons"><button class="btn secondary" data-action="close-modal">Cancelar</button><button class="btn primary" data-action="photo-annotate-save" data-index="${idx}">Guardar copia anotada</button></div>`,{wide:true});const canvas=$('#annotation-canvas'),ctx=canvas.getContext('2d'),img=new Image();img.onload=()=>{const scale=Math.min(1,1100/img.width,650/img.height);canvas.width=Math.round(img.width*scale);canvas.height=Math.round(img.height*scale);ctx.drawImage(img,0,0,canvas.width,canvas.height);};img.src=photo.dataUrl;let drawing=false;canvas.onpointerdown=ev=>{drawing=true;canvas.setPointerCapture(ev.pointerId);ctx.beginPath();ctx.moveTo(ev.offsetX,ev.offsetY);ctx.strokeStyle=$('#annotation-color').value;ctx.lineWidth=Math.max(3,canvas.width/220);ctx.lineCap='round';};canvas.onpointermove=ev=>{if(!drawing)return;ctx.lineTo(ev.offsetX,ev.offsetY);ctx.stroke();};canvas.onpointerup=()=>drawing=false;canvas.onpointercancel=()=>drawing=false;return;}
 if(a==='annotation-clear'){const idx=Number($('#modal-root [data-action="photo-annotate-save"]')?.dataset.index),photo=state.report?.photos[idx],canvas=$('#annotation-canvas');if(photo&&canvas){const img=new Image();img.onload=()=>{const ctx=canvas.getContext('2d');ctx.clearRect(0,0,canvas.width,canvas.height);ctx.drawImage(img,0,0,canvas.width,canvas.height);};img.src=photo.dataUrl;}return;}
 if(a==='photo-annotate-save'){const idx=Number(button.dataset.index),photo=state.report.photos[idx],canvas=$('#annotation-canvas');if(!photo||!canvas)throw new Error('No se encontró la edición.');const annotated=canvas.toDataURL('image/jpeg',.88);state.report.photos.push({id:uid(),dataUrl:annotated,caption:`Copia anotada de la evidencia ${idx+1}. Original conservado sin cambios.`,tag:photo.tag||'',originalPhotoId:photo.id});markDirty();await persist();closeModal();render();toast('Copia anotada añadida; la fotografía original permanece intacta.');return;}
 if(a==='ai'){await aiDialog();return;}if(a==='ai-generate'){button.disabled=true;try{await generateAi();}finally{button.disabled=false;}return;}
 if(a==='ai-apply'){if(state.report.status!=='Borrador')throw new Error('Devuelve el informe a Borrador para incorporar cambios.');state.report[button.dataset.target]=$('#ai-output').value;state.report.history.push({at:new Date().toISOString(),action:`Texto del asistente revisado e incorporado: ${button.dataset.target}`});markDirty();await persist();closeModal();render();return;}
 if(a==='sync-now'){await persist();await synchronize();if(state.view==='sync'){await reload();render();}else toast(syncState.message);return;}
 if(a==='login'){button.disabled=true;try{await login($('#login-email').value,$('#login-password').value,$('#setup-token')?.value||'');await synchronize();await reload();render();}finally{button.disabled=false;}return;}
 if(a==='logout'){await logout();state.view='dashboard';render();return;}
 if(a==='conflict-view'){await compareConflict(button.dataset.key);return;}
 if(a==='conflict-resolve'){const key=button.dataset.key,entry=await db.get('meta',key);if(button.dataset.choice==='local'&&entry?.value.data?.status==='Emitido'){const [,kind,id]=key.split(':'),local=await db.get(kind,id),revision=reviseReport(local);revision.parentId=id;revision.revision=Math.max(local.revision||0,entry.value.data.revision||0)+1;await db.saveEntity('reports',revision);await db.resolveConflict(key,'remote');closeModal();await openReport(revision.id);toast('Tus cambios se conservaron en una nueva revisión.');void synchronize();return;}await db.resolveConflict(key,button.dataset.choice);closeModal();await synchronize();await reload();render();return;}
 if(a==='install'){if(installPrompt){await installPrompt.prompt();installPrompt=null;}else toast('Usa el menú del navegador: Instalar aplicación o Agregar a pantalla de inicio.');return;}
 if(a==='check-update'){await updateRegistration?.update();toast('Buscando una nueva versión…');return;}
 if(a==='apply-update'){await persist();updateRegistration?.waiting?.postMessage({type:'ACTIVATE'});return;}
 if(a==='signature-clear'){if(state.report.status!=='Borrador')return;state.report[button.dataset.key]='';const canvas=$(`canvas[data-signature="${button.dataset.key}"]`);canvas?.getContext('2d').clearRect(0,0,canvas.width,canvas.height);markDirty();return;}
 const adds={'measurement-add':['measurements',{id:uid(),label:'',value:'',unit:'',reference:''}],'check-add':['checklist',{id:uid(),label:'Nueva verificación',condition:'',notes:''}],'asset-add':['assets',{id:uid(),tag:'',name:'',model:'',serial:'',notes:''}],'action-add':['actions',{id:uid(),description:'',priority:'Media',owner:'',dueDate:'',status:'Pendiente'}],'item-add':['proposalItems',{id:uid(),description:'',quantity:'1',unit:'un',price:'0'}]};
 if(adds[a]){if(state.report.status!=='Borrador')return;const [key,value]=adds[a];state.report[key].push(value);markDirty();await persist();render();return;}
 const removes={'measurement-remove':'measurements','check-remove':'checklist','asset-remove':'assets','action-remove':'actions','item-remove':'proposalItems','photo-remove':'photos'};
 if(removes[a]){if(state.report.status!=='Borrador')return;if(a==='photo-remove'){const photo=state.report.photos[Number(button.dataset.index)];for(const f of state.report.findings)f.photoIds=f.photoIds.filter(id=>id!==photo.id);}state.report[removes[a]].splice(Number(button.dataset.index),1);markDirty();await persist();render();return;}
}
document.addEventListener('click',ev=>{const b=ev.target.closest('[data-action]');if(!b)return;ev.preventDefault();handleAction(b).catch(err=>{if(err.name!=='AbortError')toast(err.message,true);});});
document.addEventListener('keydown',ev=>{if(ev.key==='Escape')closeModal();if((ev.ctrlKey||ev.metaKey)&&ev.key==='s'){ev.preventDefault();persist().then(()=>toast('Cambios guardados.'));}});
document.addEventListener('submit',ev=>{if(['catalog-form','operation-form','team-form','workspace-form'].includes(ev.target.id)){ev.preventDefault();document.querySelector(`[data-action="${({'catalog-form':'catalog-save','operation-form':'operation-save','team-form':'team-save','workspace-form':'workspace-save'})[ev.target.id]}"]`)?.click();}});
document.addEventListener('input',ev=>{if(ev.target.id==='template-search'){state.templateQuery=ev.target.value;const position=ev.target.selectionStart;render();const input=$('#template-search');input?.focus();input?.setSelectionRange(position,position);return;}workspaceInput(ev);enterpriseInput(ev,enterpriseContext());if(ev.target.id==='report-search'){state.query=ev.target.value;const list=filteredReports();$('#report-results').innerHTML=list.length?list.map(reportCard).join(''):empty('Sin resultados','Prueba otro término de búsqueda.');}});
document.addEventListener('change',async ev=>{try{if(ev.target.id==='template-group'){state.templateGroup=ev.target.value;render();return;}if(ev.target.id==='pending-filter'){await renderRecoveryStatus(enterpriseContext());return;}await enterpriseChange(ev,enterpriseContext());workspaceChange(ev,state);if(ev.target.matches('[data-extra-equipment]')){if(state.report.status!=='Borrador')return;const asset=state.report.assets[Number(ev.target.dataset.extraEquipment)],record=state.equipment.find(a=>a.id===ev.target.value);if(record)Object.assign(asset,{equipmentId:record.id,tag:record.tag,name:record.name,model:[record.brand,record.model].filter(Boolean).join(' '),serial:record.serial,notes:record.notes});else asset.equipmentId='';markDirty();await persist();render();return;}if(ev.target.matches('[data-report-catalog]')){if(state.report.status!=='Borrador')return;const kind=ev.target.dataset.reportCatalog,id=ev.target.value;if(!id){const key={customers:'customerRef',sites:'siteRef',equipment:'equipmentRef'}[kind];state.report[key]='';if(kind==='customers'){state.report.siteRef='';state.report.equipmentRef='';}if(kind==='sites')state.report.equipmentRef='';}else{const row=state[kind].find(r=>r.id===id);if(kind==='customers')selectCustomer(state.report,row);if(kind==='sites')selectSite(state.report,row,state.customers);if(kind==='equipment')selectEquipment(state.report,row,state.sites,state.customers);}markDirty();await persist();render();return;}if(ev.target.matches('[data-finding-photo]')){if(state.report.status!=='Borrador')return;const finding=state.report.findings[Number(ev.target.dataset.findingPhoto)];finding.photoIds=[...document.querySelectorAll(`[data-finding-photo="${ev.target.dataset.findingPhoto}"]:checked`)].map(el=>el.value);markDirty();await persist();}if(ev.target.id==='company-switch'){await persist();state.companyId=ev.target.value;state.report=null;state.view='dashboard';await db.setMeta('activeCompany',state.companyId);render();}if(ev.target.id==='status-filter'){state.filter=ev.target.value;render();}if(ev.target.id==='logo-file'){const file=ev.target.files[0];if(file){state.companyEdit.logo=await imageData(file,{logo:true});$('#company-logo').innerHTML=`<img src="${state.companyEdit.logo}" alt="Logo">`;}}if(ev.target.id==='photos-input'){if(state.report.status!=='Borrador')return;const files=[...ev.target.files];if(state.report.photos.length+files.length>24)throw new Error('Se permiten hasta 24 imágenes por informe.');toast('Preparando fotografías…');for(const file of files){state.report.photos.push({id:uid(),dataUrl:await imageData(file),caption:'',tag:''});markDirty();await persist();}render();}}catch(error){toast(error.message,true);}});
window.addEventListener('beforeinstallprompt',ev=>{ev.preventDefault();installPrompt=ev;});
async function setupSW(){if(!('serviceWorker'in navigator))return;try{updateRegistration=await navigator.serviceWorker.register('/sw.js');const pending=async()=>{if(!updateRegistration.waiting)return;if($('#modal-root').innerHTML||state.companyEdit){toast('Actualización disponible. Se aplicará al volver a abrir la aplicación.');return;}try{await persist();await db.setMeta('resume',{view:state.view,tab:state.tab,reportId:state.report?.id});updateRegistration.waiting.postMessage({type:'ACTIVATE'});}catch{toast('Nueva versión disponible. Guarda tus cambios antes de actualizar.',true);}};pending();updateRegistration.addEventListener('updatefound',()=>{const worker=updateRegistration.installing;worker?.addEventListener('statechange',()=>{if(worker.state==='installed'&&navigator.serviceWorker.controller)pending();});});let refreshing=false;navigator.serviceWorker.addEventListener('controllerchange',()=>{if(!refreshing){refreshing=true;location.reload();}});}catch(err){console.warn('Offline shell unavailable',err);toast('El navegador no pudo preparar el modo offline. Vuelve a abrir con conexión.',true);}}
async function init(){bindGlobalErrors();await reload();if(!state.companies.length){const c=newCompany();c.id='solis-default';c.name='SOLIS INGENIERÍA Y SERVICIOS SpA';c.tradeName='SOLIS Ingeniería';c.taxId='78.280.616-5';c.city='San Pedro de Atacama';c.address='Puritama, San Pedro de Atacama';c.email='solisingenieria.sis@gmail.com';c.phone='+56 9 7603 8420';c.website='solisingenieria.cl';try{const blob=await (await fetch('/solis-logo.png')).blob();c.logo=await new Promise(res=>{const reader=new FileReader();reader.onload=()=>res(reader.result);reader.readAsDataURL(blob);});}catch{}try{await db.saveEntity('companies',c);}catch(error){if(error.code!=='LOCAL_CHANGED'||!await db.get('companies',c.id))throw error;}await reload();}state.companyId=await db.meta('activeCompany',state.companies[0].id);if(!state.companies.some(c=>c.id===state.companyId))state.companyId=state.companies[0].id;await db.migrateLegacy(company());await reload();syncState.lastSync=await db.meta('lastSync');const resume=await db.meta('resume');if(resume){await db.setMeta('resume',null);if(resume.reportId){const saved=await db.get('reports',resume.reportId);if(saved&&!saved._sync?.deleted){state.report=normalizeReport(saved,company());state.view=resume.view;state.tab=resume.tab||0;}}}render();subscribeSync(()=>{updateSyncUI();if(syncState.user?.role==='client'){state.view='portal';render();return;}if(state.view==='portal'){state.view='sync';render();return;}if(state.view==='sync')renderRecoveryStatus(enterpriseContext()).catch(error=>toast(error.message,true));if(state.view==='editor'&&state.report){const current=state.report;db.get('reports',current.id).then(latest=>{if(state.report===current&&mayRefreshReport(current,latest,{dirty,pending:savePending>0})){state.report=normalizeReport(latest,company());render();return;}if(state.report===current&&mayAdoptSyncMetadata(current,latest)){current._sync=latest._sync;const label=$('#editor-sync-label');if(label)label.textContent=labelSync(current);}});}if(!dirty&&['dashboard','reports','directory','equipment','templates','tasks','workOrders','manuals','alertRules'].includes(state.view)&&['synced','conflict'].includes(syncState.status)){reload().then(()=>{if(!$('#modal-root').innerHTML)render();});}});const deep=new URLSearchParams(location.hash.slice(1)).get('equipment');if(deep&&state.equipment.some(x=>x.id===deep)){const row=state.equipment.find(x=>x.id===deep);state.companyId=row.companyId;await handleEnterpriseAction({dataset:{action:'catalog-history',id:deep}},enterpriseContext());}startSync();await setupSW();}
init().catch(err=>{$('#app').innerHTML=`<div class="boot"><h1>No pudimos abrir el almacenamiento</h1><p>${e(err.message)}</p><p>Activa el almacenamiento del navegador o abre un perfil normal.</p></div>`;});
